// Webhook POST offer.created do backend Realoca AI. Sem fallback para IDs falsos.
const item = $input.first().json;
const p = item.body && typeof item.body === 'object' ? item.body : item;
const required = ['event_id','case_id','attempt_id','task_id','task_title',
  'candidate_employee_id','candidate_name','channel_user_id','response_deadline_at','due_at','message'];
for (const f of required) {
  if (typeof p[f] !== 'string' || p[f].trim() === '') throw new Error('INVALID_OFFER: ' + f);
}
if (p.event_type !== 'offer.created' || p.channel !== 'slack') throw new Error('INVALID_OFFER: event_type/channel');
if (typeof p.estimated_hours !== 'number' || !Number.isFinite(p.estimated_hours) || p.estimated_hours <= 0)
  throw new Error('INVALID_OFFER: estimated_hours');
if (!/(Z|[+-][0-9]{2}:[0-9]{2})$/i.test(p.response_deadline_at) ||
    !/(Z|[+-][0-9]{2}:[0-9]{2})$/i.test(p.due_at)) throw new Error('INVALID_OFFER: timestamps must include timezone');
const deadline = new Date(p.response_deadline_at).getTime();
const due = new Date(p.due_at).getTime();
if (!Number.isFinite(deadline) || !Number.isFinite(due) || deadline <= Date.now())
  throw new Error('INVALID_OFFER: response deadline expired or invalid');
// A mensagem é a aprovada pelo backend; o n8n não decide quem substitui quem.
return [{json: {...p}}];

// Transforma o resultado do Slack no schema estrito A13; não atribui tarefa.
const x = $input.first().json;
const attemptId = String(x.attempt_id || '').trim();
const decision = String(x.decision || '').toLowerCase().trim();
if (!attemptId || attemptId.length > 130) throw new Error('INVALID_CALLBACK: attempt_id');
if (!['accepted','declined','expired'].includes(decision)) throw new Error('INVALID_CALLBACK: decision');
if (x.channel !== 'slack' || x.source !== 'slack') throw new Error('INVALID_CALLBACK: channel/source');
let when;
let reason = null;
if (decision === 'expired') {
  const deadline = String(x.response_deadline_at || '').trim();
  if (!/(Z|[+-][0-9]{2}:[0-9]{2})$/i.test(deadline))
    throw new Error('INVALID_CALLBACK: expiry deadline requires timezone');
  when = new Date(deadline);
  if (!Number.isFinite(when.getTime()) || Date.now() < when.getTime())
    throw new Error('INVALID_CALLBACK: not yet expired');
  reason = 'Prazo de resposta expirado';
} else {
  const timestamp = String(x.responded_at || '').trim();
  if (!/(Z|[+-][0-9]{2}:[0-9]{2})$/i.test(timestamp))
    throw new Error('INVALID_CALLBACK: responded_at requires timezone');
  when = new Date(timestamp);
  if (!Number.isFinite(when.getTime())) throw new Error('INVALID_CALLBACK: responded_at');
  if (decision === 'declined') reason = (String(x.decline_reason || '').trim() || 'Recusa registrada no Slack').slice(0,2000);
}
const eventType = decision === 'accepted' ? 'offer.accepted' : decision === 'declined' ? 'offer.refused' : 'offer.expired';
// Novo ID para callback, distinto do event_id de offer.created. Estável para retries.
const eventId = 'evt-n8n-' + attemptId + '-' + (decision === 'declined' ? 'refused' : decision);
return [{json: {
  event_id: eventId, event_type: eventType, attempt_id: attemptId,
  channel:'slack', occurred_at: when.toISOString(), reason
}}];
